        json.dumps({
            \"output_text\": \"\",
            \"output\": [{
                \"type\": \"message\",
                \"content\": [
                    {\"type\": \"output_text\", \"text\": \"hello \"},
                    {\"type\": \"output_text\", \"text\": \"world\"},
                ],
            }],
        }).encode(),
        {\"x-request-id\": \"req_test\"},
    )


original_urlopen = openai_client.urlopen
try:
    openai_client.urlopen = successful_urlopen
    result = openai_client.send_prompt(
        \"private prompt\",
        api_key=\"test-key\",
        model=\"test-model\",
        instructions=\"Be brief\",
        temperature=0.2,
    )
