def send_prompt(
    prompt: str,
    *,
    api_key: Optional[str] = None,
    model: str = DEFAULT_MODEL,
    instructions: Optional[str] = None,
    timeout: float = DEFAULT_TIMEOUT,
    **request_options: Any,
) -> dict[str, Any]:
    """Send one private text prompt using a temporary client."""
    client = OpenAIClient(api_key=api_key, model=model, timeout=timeout)
    return client.send_prompt(
        prompt,
        instructions=instructions,
        **request_options,
    )


